#Requires -Version 7.0
[CmdletBinding(SupportsShouldProcess)]
param()
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$workspace='<repo>'
$relative='docs/evidence/release15/frozen-fdee7a2/live-ui/runtime-responsiveness-producers'
$destination=Join-Path $workspace $relative
if(Test-Path $destination){throw 'Preserve existing producer directory'}
if(-not $PSCmdlet.ShouldProcess($destination,'Retain analyzed observer, diagnosis producer and append-only preparation/qualification receipt')){return}
$sources=@('/tmp/WatchWordpairsOwnedRuntime.ps1','/tmp/InspectWordpairsResponsiveness.ps1',$PSCommandPath)
$checks=@(foreach($source in $sources){$tokens=$null;$errorsFound=$null;[void][Management.Automation.Language.Parser]::ParseFile($source,[ref]$tokens,[ref]$errorsFound);$issues=@(Invoke-ScriptAnalyzer -Path $source -Severity Warning,Error);if(@($errorsFound).Count -or $issues.Count){throw 'Producer parser/analyzer failed'};[ordered]@{source=$source;sha256=(Get-FileHash $source).Hash;parserErrors=0;analyzerIssues=0}})
$placeholderOutput=Join-Path $workspace 'docs/evidence/release15/frozen-fdee7a2/live-ui/observer-whatif-placeholder'
$whatIf=@(& /tmp/WatchWordpairsOwnedRuntime.ps1 -UnitName wordpairs-replay-example.service -ControlGroup /user.slice/wordpairs-replay-example.service -InvocationId 00000000000000000000000000000000 -RuntimeDirectory (Join-Path $workspace '.mcpServer/ui-00000000000000000000000000000000') -RunId 00000000-0000-0000-0000-000000000000 -SourceHead fdee7a2569bb4742e008977e2a9cd7d312def859 -SourceManifest (Join-Path $workspace 'docs/evidence/release15/frozen-fdee7a2/source-inventory.json') -OutputDirectory $placeholderOutput -WhatIf 6>&1 | ForEach-Object ToString)
if(Test-Path $placeholderOutput){throw 'WhatIf unexpectedly produced measurements'}
[void][IO.Directory]::CreateDirectory($destination)
$pins=@(foreach($item in $checks){$copy=Join-Path $destination (Split-Path $item.source -Leaf);Copy-Item -LiteralPath $item.source -Destination $copy;if((Get-FileHash $copy).Hash -cne $item.sha256){throw 'Producer copy mismatch'};[ordered]@{source=$item.source;retained=$copy;sha256=$item.sha256;parserErrors=0;analyzerIssues=0;originalRetained=$true}})
$diagnosis=Join-Path $workspace 'docs/evidence/release15/frozen-fdee7a2/live-ui/runtime-responsiveness-diagnosis.json'
$effective=Join-Path $workspace 'docs/evidence/release15/frozen-fdee7a2/live-ui/runtime-responsiveness-effective.json'
$preparation=[ordered]@{recordedAt=[DateTimeOffset]::Now.ToString('o');classification='Optional operational observer preparation only; no runtime/test/model/provider execution';sessionId='Codex-20261030T194802Z-plugin-session';requestId='req-20261030T233950Z-runtime-responsiveness-diagnosis';parentSessionId='Codex-20261027T100516Z-plugin-session';parentRequestId='req-20261030T203656Z-cline-beam-release';diagnosis=@{path=$diagnosis;sha256=(Get-FileHash $diagnosis).Hash;unchanged=$true};effective=@{path=$effective;sha256=(Get-FileHash $effective).Hash;retainedAt=(Get-Item $effective).LastWriteTime.ToString('o')};producerPins=$pins;whatIf=@{executedAt=[DateTimeOffset]::Now.ToString('o');placeholderIdentitiesOnly=$true;message=$whatIf;outputCreated=$false;measurementsExecuted=$false};parameters=@('UnitName: exact owned .service unit','SystemdScope: User default or System','ControlGroup: exact systemctl ControlGroup','InvocationId: exact systemctl InvocationID','RuntimeDirectory: exact existing .mcpServer/ui-<32hex> with validated database-owner.json','RunId: existing validation chain runId','SourceHead: exact successor40hex revision','SourceManifest: matching frozen source-inventory.json','OutputDirectory: fresh path under workspace docs/evidence','IntervalSeconds: default2, allowed2..30');outputs=@('samples.jsonl: cgroup CPU/RSS/process membership, safe owned DB state/wait/locks/blockers, scheduling/overhead/errors','observer.json: exact unit/runtime/source/run ownership, native exits/times, missing intervals/errors/retirement, samples/producer hashes and limits');qualifications=@('Latest root directive supersedes diagnosis minimalNextMeasurements item1 focused-run suggestion: root will attach observer to the existing full five-lane chain live-ui phase, which already includes2..15and10/15. No separate focused game run, new result producer or acceptance SLA is requested.','Existing diagnosis currentRequirements.readAt is synthesis time, not measured exact network-read instant. The retainedAt timestamp here is the saved effective-response file timestamp following successful own-plugin read.','No ownership or runtime measurement has been validated against live resources by this agent. Parser/PSSA and placeholder-only WhatIf do not establish operating correctness.','DB sampling retires when the original owner receipt disappears and never discovers a successor. Cgroup-only samples can continue into later lanes until exact unit exits. DB metadata gaps or docker teardown races stay explicit.','No pool/timeout/cap/worker increases, app instrumentation, source/config/requirements mutations or HV occurred.','PowerShell observer self-inspection caught and corrected a DB-retirement branch that initially also suppressed cgroup sampling. No actual measurements were made with that intermediate draft.');scopeResult='PREPARED_NOT_EXECUTED'}
$target=Join-Path $destination 'preparation.json'
$preparation|ConvertTo-Json -Depth 100|Set-Content $target
$now=Get-Date -Format s
$response=@"
$now - Read-only responsiveness diagnosis retained at $diagnosis, SHA256 $((Get-FileHash $diagnosis).Hash). The 35 inspected source pins match the frozen fdee7a2 inventory of 348 paths. Fresh effective layer-1 requirements contain 31 FR, 43 TR and 94 TEST records, retained at $effective, SHA256 $((Get-FileHash $effective).Hash).

The observed native 10-player game is incomplete in round 2 with 17 solves; no driver body errors or counted uncertain UI retries were recorded. Completed browser timing contains an answer at 11601.008 ms, match GET at 11731.103 ms, presence at 10861.253 ms and session reads near 8.5 seconds. These are browser completion durations with filtered and bounded detail capture, not SQL/server spans or exact page 7 command attribution. Source supports possible contention from a shared pool of 3 connections, room read/write locks, fanout refetches and awaited foreground catch-up/publication. None is proved the runtime bottleneck.

Current criteria require a valid canonical Retry, preserved data and scores, the complete 2 through 15 player matrix and 20-second answer stages. No numeric HTTP SLA was found in current normative bodies, conditions or acceptance criteria. Correct native Retry gating can verify recovery while responsiveness remains qualified. No timeout, cap, pool or worker increase is proposed.

The optional operational observer is prepared only at $(Join-Path $destination 'WatchWordpairsOwnedRuntime.ps1'). All 3 retained producers have zero parser and analyzer issues; the placeholder-only WhatIf produced no measurement output or runtime/database reads. Preparation receipt: $target, SHA256 $((Get-FileHash $target).Hash). Root will attach it to the existing chain's live-ui phase after obtaining exact unit, cgroup, invocation, run, source and runtime identities. No separate test run, result producer or SLA is added. It samples the owned cgroup and receipt/label-verified game database metadata, omits SQL text, credentials, environment and argv, records overhead, gaps and native exits, retires original database sampling when that runtime disappears, and observes the unit until exit. No actual measurement was performed.

FAIL: the native 10-player game is incomplete, so the release matrix is not complete. UNKNOWN: exact pending-command cause, pool waits, contemporaneous PostgreSQL waits/holders, CPU/event-loop/gateway scheduling, worker/publication timing, and the next native recovery/matrix outcome. No application edits, builds, tests, runtime launch, provider or requirements changes, or HV were performed. This is an operational diagnosis, not release acceptance. Accuracy 99%: pinned facts are separated from hypotheses. Completeness 95%: scoped source and current criteria verified, causality and observer runtime remain unverified. Own session: Codex-20261030T194802Z-plugin-session / req-20261030T233950Z-runtime-responsiveness-diagnosis. Parent root request: req-20261030T203656Z-cline-beam-release.
"@
[IO.File]::WriteAllText('/tmp/wordpairs-runtime-responsiveness-result.txt',$response)
[pscustomobject]@{path=$target;sha256=(Get-FileHash $target).Hash;producerPins=$pins;observerExecuted=$false;resultText='/tmp/wordpairs-runtime-responsiveness-result.txt'}|ConvertTo-Json -Depth 20
